content.text:
{
  "name": "仿真场景组件",
  "name_en": "Simulation Scene Component",
  "manufacturer": "",
  "description": "这是一个非物理软件组件，用于定义、编译、初始化和更新仿真场景。它管理场景规格、实体、传感器、地形、多环境布局及共享传感上下文，并可将场景 XML 与网格资源导出到目录或压缩包，供实验或机器人仿真使用。",
  "description_en": "This is a non-physical software component for defining, compiling, initializing, and updating a simulation scene. It manages scene specifications, entities, sensors, terrain, multi-environment layout, and shared sensor context, and can export scene XML and mesh assets to a directory or archive for laboratory or robotics simulation use.",
  "actions": [
    {
      "action_name": "auto-compile",
      "description": "编译仿真场景规格以生成可用于仿真的场景。",
      "description_en": "Compile the simulation scene specification into a scene usable by the simulator."
    },
    {
      "action_name": "auto-write",
      "description": "将场景 XML 和网格资源写入目录，或导出为压缩包。",
      "description_en": "Write the scene XML and mesh assets to a directory, or export them as an archive."
    },
    {
      "action_name": "auto-to_zip",
      "description": "将场景导出为压缩包（已弃用）。",
      "description_en": "Export the scene as a zip archive (deprecated)."
    },
    {
      "action_name": "auto-spec",
      "description": "获取场景规格。",
      "description_en": "Get the scene specification."
    },
    {
      "action_name": "auto-env_origins",
      "description": "获取各仿真环境的原点位置。",
      "description_en": "Get the origin positions of the simulation environments."
    },
    {
      "action_name": "auto-env_spacing",
      "description": "获取仿真环境之间的间距。",
      "description_en": "Get the spacing between simulation environments."
    },
    {
      "action_name": "auto-entities",
      "description": "获取场景中的实体集合。",
      "description_en": "Get the set of entities in the scene."
    },
    {
      "action_name": "auto-sensors",
      "description": "获取场景中的传感器集合。",
      "description_en": "Get the set of sensors in the scene."
    },
    {
      "action_name": "auto-terrain",
      "description": "获取场景地形配置或对象。",
      "description_en": "Get the scene terrain configuration or object."
    },
    {
      "action_name": "auto-num_envs",
      "description": "获取仿真环境数量。",
      "description_en": "Get the number of simulation environments."
    },
    {
      "action_name": "auto-device",
      "description": "获取仿真所用的计算设备。",
      "description_en": "Get the compute device used by the simulation."
    },
    {
      "action_name": "auto-sensor_context",
      "description": "获取共享传感上下文。",
      "description_en": "Get the shared sensor context."
    },
    {
      "action_name": "auto-initialize",
      "description": "使用仿真模型和数据初始化场景及所需的传感上下文。",
      "description_en": "Initialize the scene and any required sensor context using the simulation model and data."
    },
    {
      "action_name": "auto-reset",
      "description": "重置全部或指定的仿真环境。",
      "description_en": "Reset all or selected simulation environments."
    },
    {
      "action_name": "auto-update",
      "description": "按时间步更新仿真场景状态。",
      "description_en": "Update the simulation scene state for a timestep."
    },
    {
      "action_name": "auto-write_data_to_sim",
      "description": "将场景数据写入仿真器。",
      "description_en": "Write scene data into the simulator."
    }
  ],
  "tag_hints": [
    "simulation scene",
    "MuJoCo simulation",
    "scene compilation",
    "multi-environment simulation",
    "sensor context",
    "terrain setup",
    "XML asset export"
  ]
}

